def is_prime(num: int) -> bool:
    if num <= 1:
        return False
    if num in [2, 3]:
        return True
    if num % 2 == 0:
        return False
    if num % 3 == 0:
        return False
    i = 6
    while i <= num ** 0.5:
        if num % i == 0:
            return False
        if num % (i + 2) == 0:
            return False
        i += 6
    return True

