def hanoi_double_iterative(n: int) -> int:
    """
    Iterative algorithm to determine the minimum number of moves necessary to transfer 2n discs from the A pole to the C pole in a double-disc Hanoi Towers setup.
    """
    if n == 0:
        return 0
    if n == 1:
        return 2
    else:
        return 2 * hanoi_double_iterative(n - 1) + 1
